questions.solution:
#include <iostream>
using namespace std;
void reverseArray(int a[],int n){for(int i=0,j=n-1;i<j;i++,j--){int t=a[i];a[i]=a[j];a[j]=t;}}
int main(){int n,a[100];cin>>n;for(int i=0;i<n;i++)cin>>a[i];reverseArray(a,n);for(int i=0;i<n;i++){if(i)cout<<' ';cout<<a[i];}}
